import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr,
    .param .u64 bias_ptr,
    .param .u32 n_elements,
    .param .u32 has_bias
)
{
    .reg .u64 %rd<13>;
    .reg .u32 %r<22>;
    .reg .f32 %f<5>;
    .reg .pred %p<12>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [output_ptr];
    ld.param.u64 %rd4, [bias_ptr];
    ld.param.u32 %r1, [n_elements];
    ld.param.u32 %r2, [has_bias];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %ntid.x;
    mov.u32 %r5, %tid.x;
    mad.lo.s32 %r6, %r3, %r4, %r5;

    setp.ge.s32 %p1, %r6, %r1;
    @%p1 bra DONE;

    div.s32 %r7, %r6, 496;
    rem.s32 %r8, %r6, 496;
    div.s32 %r9, %r7, 508;
    rem.s32 %r10, %r7, 508;
    div.s32 %r11, %r9, 64;
    rem.s32 %r12, %r9, 64;

    mov.f32 %f1, 0f00000000;

    mov.u32 %r13, 0;
IC_LOOP:
    setp.ge.s32 %p2, %r13, 32;
    @%p2 bra IC_DONE;

    mov.u32 %r14, 0;
KH_LOOP:
    setp.ge.s32 %p3, %r14, 5;
    @%p3 bra KH_DONE;

    mul.lo.s32 %r16, %r14, 2;
    add.s32 %r17, %r10, %r16;
    sub.s32 %r17, %r17, 2;

    setp.lt.s32 %p4, %r17, 0;
    setp.gt.s32 %p5, %r17, 511;
    or.pred %p6, %p4, %p5;
    @%p6 bra KH_CONTINUE;

    mov.u32 %r15, 0;
KW_LOOP:
    setp.ge.s32 %p7, %r15, 9;
    @%p7 bra KW_DONE;

    mul.lo.s32 %r18, %r15, 3;
    add.s32 %r19, %r8, %r18;
    sub.s32 %r19, %r19, 4;

    setp.lt.s32 %p8, %r19, 0;
    setp.gt.s32 %p9, %r19, 511;
    or.pred %p10, %p8, %p9;
    @%p10 bra KW_CONTINUE;

    mad.lo.s32 %r20, %r11, 32, %r13;
    mad.lo.s32 %r20, %r20, 512, %r17;
    mad.lo.s32 %r20, %r20, 512, %r19;

    mul.wide.s32 %rd5, %r20, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f2, [%rd6];

    mad.lo.s32 %r21, %r12, 32, %r13;
    mad.lo.s32 %r21, %r21, 5, %r14;
    mad.lo.s32 %r21, %r21, 9, %r15;

    mul.wide.s32 %rd7, %r21, 4;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f3, [%rd8];

    fma.rn.f32 %f1, %f2, %f3, %f1;

KW_CONTINUE:
    add.s32 %r15, %r15, 1;
    bra KW_LOOP;
KW_DONE:

KH_CONTINUE:
    add.s32 %r14, %r14, 1;
    bra KH_LOOP;
KH_DONE:

    add.s32 %r13, %r13, 1;
    bra IC_LOOP;
IC_DONE:

    setp.eq.s32 %p11, %r2, 0;
    @%p11 bra STORE;

    mul.wide.s32 %rd9, %r12, 4;
    add.s64 %rd10, %rd4, %rd9;
    ld.global.f32 %f4, [%rd10];
    add.f32 %f1, %f1, %f4;

STORE:
    mul.wide.s32 %rd11, %r6, 4;
    add.s64 %rd12, %rd3, %rd11;
    st.global.f32 [%rd12], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size,
                                 stride=stride, padding=padding, dilation=dilation,
                                 bias=bias)
        self.register_buffer("zero_bias", torch.zeros(out_channels))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        x = x.contiguous()
        weight = self.conv2d.weight.contiguous()

        has_bias_flag = 1 if self.conv2d.bias is not None else 0
        if self.conv2d.bias is not None:
            bias_tensor = self.conv2d.bias.contiguous()
        else:
