        N = B * OC * H_out * W_out
        block = (256, 1, 1)
        grid = ((N + block[0] - 1) // block[0], 1, 1)

        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=grid,
            block=block,
            arguments=[x, weight, output, bias_tensor, i32(N), i32(has_bias_flag)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

